package io.github.iamthecodedecoded.queststateexporter;

final class ExportScheduler
{
    static final int LOGIN_SETTLE_TICKS = 5;
    static final int HEARTBEAT_TICKS = 500;
    static final int MAX_CONSECUTIVE_RETRIES = 3;

    enum ExportRequest
    {
        NONE,
        CAPTURE,
        FORCE
    }

    private boolean loggedIn;
    private boolean pending;
    private boolean pendingForce;
    private boolean pendingResetsRetryBudget;
    private boolean retryExhausted;
    private int ticksRemaining;
    private int heartbeatTicksRemaining;
    private int consecutiveRetries;

    synchronized void loggedIn()
    {
        loggedIn = true;
        pending = true;
        pendingForce = true;
        pendingResetsRetryBudget = true;
        retryExhausted = false;
        ticksRemaining = LOGIN_SETTLE_TICKS;
        heartbeatTicksRemaining = HEARTBEAT_TICKS;
        consecutiveRetries = 0;
    }

    synchronized void loggedOut()
    {
        loggedIn = false;
        pending = false;
        pendingForce = false;
        pendingResetsRetryBudget = false;
        retryExhausted = false;
        ticksRemaining = 0;
        heartbeatTicksRemaining = 0;
        consecutiveRetries = 0;
    }

    synchronized void varbitChanged()
    {
        if (loggedIn && !pending && !retryExhausted)
        {
            pending = true;
            pendingForce = false;
            pendingResetsRetryBudget = false;
            ticksRemaining = 1;
        }
    }

    synchronized boolean retry()
    {
        if (!loggedIn || consecutiveRetries >= MAX_CONSECUTIVE_RETRIES)
        {
            retryExhausted = loggedIn;
            return false;
        }
        consecutiveRetries++;
        pending = true;
        pendingForce = true;
        pendingResetsRetryBudget = false;
        ticksRemaining = LOGIN_SETTLE_TICKS;
        return true;
    }

    synchronized void exportSucceeded()
    {
        consecutiveRetries = 0;
        retryExhausted = false;
    }

    synchronized ExportRequest gameTick()
    {
        if (!loggedIn)
        {
            return ExportRequest.NONE;
        }

        heartbeatTicksRemaining--;
        if (heartbeatTicksRemaining <= 0)
        {
            if (!pending)
            {
                resetHeartbeatAndRetryBudget();
                return ExportRequest.FORCE;
            }
            pendingForce = true;
            pendingResetsRetryBudget = true;
        }

        if (!pending)
        {
            return ExportRequest.NONE;
        }
        if (--ticksRemaining > 0)
        {
            return ExportRequest.NONE;
        }

        pending = false;
        ExportRequest request = pendingForce ? ExportRequest.FORCE : ExportRequest.CAPTURE;
        pendingForce = false;
        if (pendingResetsRetryBudget)
        {
            resetHeartbeatAndRetryBudget();
        }
        pendingResetsRetryBudget = false;
        return request;
    }

    private void resetHeartbeatAndRetryBudget()
    {
        heartbeatTicksRemaining = HEARTBEAT_TICKS;
        consecutiveRetries = 0;
        retryExhausted = false;
    }
}

package io.github.iamthecodedecoded.queststateexporter;

import java.util.HashSet;
import java.util.Set;

final class PayloadDeduplicator
{
    private final Set<String> queued = new HashSet<>();
    private String lastWritten;

    synchronized boolean tryQueue(String fingerprint)
    {
        requireFingerprint(fingerprint);
        if (fingerprint.equals(lastWritten) || queued.contains(fingerprint))
        {
            return false;
        }
        queued.add(fingerprint);
        return true;
    }

    synchronized void succeeded(String fingerprint)
    {
        requireFingerprint(fingerprint);
        queued.remove(fingerprint);
        lastWritten = fingerprint;
    }

    synchronized void failed(String fingerprint)
    {
        requireFingerprint(fingerprint);
        queued.remove(fingerprint);
    }

    synchronized void forceNext()
    {
        lastWritten = null;
    }

    private static void requireFingerprint(String fingerprint)
    {
        if (fingerprint == null || fingerprint.trim().isEmpty())
        {
            throw new IllegalArgumentException("fingerprint must not be blank");
        }
    }
}

package io.github.iamthecodedecoded.queststateexporter;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.VarPlayerID;

final class QuestSnapshotBuilder
{
    static final String SCHEMA_VERSION = "1.0.0";
    static final String EXPORT_VERSION = "1.0.0";

    private QuestSnapshotBuilder()
    {
    }

    static Map<String, Object> capture(Client client, String accountName, Instant capturedAt)
    {
        Objects.requireNonNull(client, "client");
        Objects.requireNonNull(capturedAt, "capturedAt");
        if (accountName == null || accountName.trim().isEmpty())
        {
            throw new IllegalArgumentException("Account name must not be blank.");
        }

        int finished = 0;
        int inProgress = 0;
        int notStarted = 0;
        List<Map<String, Object>> entries = new ArrayList<>(Quest.values().length);
        for (Quest quest : Quest.values())
        {
            QuestState state = Objects.requireNonNull(
                quest.getState(client),
                "RuneLite returned no state for " + quest.name());
            switch (state)
            {
                case FINISHED:
                    finished++;
                    break;
                case IN_PROGRESS:
                    inProgress++;
                    break;
                case NOT_STARTED:
                    notStarted++;
                    break;
                default:
                    throw new IllegalStateException("Unsupported quest state: " + state);
            }

            Map<String, Object> entry = new LinkedHashMap<>();
            entry.put("id", quest.name());
            entry.put("name", quest.getName());
            entry.put("state", state.name());
            entries.add(entry);
        }

        int questPoints = client.getVarpValue(VarPlayerID.QP);
        if (questPoints < 0)
        {
            throw new IllegalStateException("RuneLite returned negative quest points.");
        }

        Map<String, Object> quests = new LinkedHashMap<>();
        quests.put("notStarted", notStarted);
        quests.put("inProgress", inProgress);
        quests.put("finished", finished);
        quests.put("unknown", 0);
        quests.put("total", entries.size());
        quests.put("questPoints", questPoints);
        quests.put("entries", entries);

        Map<String, Object> snapshot = new LinkedHashMap<>();
        snapshot.put("schemaVersion", SCHEMA_VERSION);
        snapshot.put("exportVersion", EXPORT_VERSION);
        snapshot.put("timestampIso", capturedAt.toString());
        snapshot.put("rsn", accountName);
        snapshot.put("quests", quests);
        return snapshot;
    }
}

package io.github.iamthecodedecoded.queststateexporter;

import static io.github.iamthecodedecoded.queststateexporter.ExportScheduler.ExportRequest;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.RuneLite;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
    name = "Quest State Exporter",
    description = "Writes only quest states and quest points to a local JSON file",
    tags = {"quest", "export", "local"})
public class QuestStateExporterPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(QuestStateExporterPlugin.class);
    private final ExportScheduler scheduler = new ExportScheduler();
    private final PayloadDeduplicator deduplicator = new PayloadDeduplicator();

    @Inject
    private Client client;

    @Inject
    private Gson gson;

    private ExecutorService writer;
    private volatile boolean running;

    @Override
    protected void startUp()
    {
        running = true;
        writer = Executors.newSingleThreadExecutor(task ->
        {
            Thread thread = new Thread(task, "quest-state-exporter-writer");
            thread.setDaemon(true);
            return thread;
        });
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            scheduler.loggedIn();
        }
        LOG.info("QSE_PLUGIN_STARTED outputDirectory={}", SnapshotWriter.OUTPUT_DIRECTORY);
    }

    @Override
    protected void shutDown()
    {
        running = false;
        scheduler.loggedOut();
        ExecutorService activeWriter = writer;
        writer = null;
        if (activeWriter == null)
        {
            return;
        }
        List<Runnable> droppedTasks = activeWriter.shutdownNow();
        LOG.info("QSE_PLUGIN_STOPPED droppedQueuedWrites={}", droppedTasks.size());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            scheduler.loggedIn();
        }
        else
        {
            scheduler.loggedOut();
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        scheduler.varbitChanged();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        ExportRequest request = scheduler.gameTick();
        if (request != ExportRequest.NONE)
        {
            if (request == ExportRequest.FORCE)
            {
                deduplicator.forceNext();
            }
            captureAndQueue();
        }
    }

    @SuppressWarnings("unchecked")
    private void captureAndQueue()
    {
        Player player = client.getLocalPlayer();
        String accountName = player == null ? null : player.getName();
        if (accountName == null || accountName.trim().isEmpty())
        {
            boolean retryScheduled = scheduler.retry();
            LOG.warn(
                "QSE_CAPTURE_DEFERRED code=LOCAL_PLAYER_UNAVAILABLE retryScheduled={} retryTicks={} recovery={}",
                retryScheduled,
                retryScheduled ? ExportScheduler.LOGIN_SETTLE_TICKS : 0,
                retryScheduled ? "automatic" : "wait_for_heartbeat_or_relogin");
            return;
        }

        Instant capturedAt = Instant.now();
        String operationId = capturedAt.toString();
        final String json;
        final String fingerprint;
        final int questCount;
        try
        {
            Map<String, Object> snapshot = QuestSnapshotBuilder.capture(client, accountName, capturedAt);
            Map<String, Object> quests = (Map<String, Object>) snapshot.get("quests");
            questCount = ((Number) quests.get("total")).intValue();
            fingerprint = accountName + "\n" + gson.toJson(quests);
            json = gson.toJson(snapshot) + System.lineSeparator();
        }
        catch (RuntimeException error)
        {
            boolean retryScheduled = scheduler.retry();
            LOG.error(
                "QSE_CAPTURE_FAILED operationId={} account={} retryScheduled={} retryTicks={} recovery={}",
                operationId,
                accountName,
                retryScheduled,
                retryScheduled ? ExportScheduler.LOGIN_SETTLE_TICKS : 0,
                retryScheduled ? "automatic" : "wait_for_heartbeat_or_relogin",
                error);
            return;
        }

        if (!deduplicator.tryQueue(fingerprint))
        {
            LOG.debug("QSE_EXPORT_SKIPPED operationId={} account={} code=UNCHANGED_OR_QUEUED", operationId, accountName);
            return;
        }

        ExecutorService activeWriter = writer;
        if (activeWriter == null)
        {
            deduplicator.failed(fingerprint);
            boolean retryScheduled = scheduler.retry();
            LOG.error(
                "QSE_QUEUE_FAILED operationId={} account={} code=WRITER_UNAVAILABLE retryScheduled={}",
                operationId,
                accountName,
                retryScheduled);
            return;
        }
        try
        {
            activeWriter.submit(() -> writeSnapshot(operationId, accountName, questCount, fingerprint, json));
        }
        catch (RejectedExecutionException error)
        {
            deduplicator.failed(fingerprint);
            boolean retryScheduled = scheduler.retry();
            LOG.error(
                "QSE_QUEUE_FAILED operationId={} account={} code=WRITER_REJECTED retryScheduled={}",
                operationId,
                accountName,
                retryScheduled,
                error);
        }
    }

    private void writeSnapshot(String operationId, String accountName, int questCount, String fingerprint, String json)
    {
        if (!running)
        {
            deduplicator.failed(fingerprint);
            LOG.debug("QSE_WRITE_CANCELLED operationId={} account={} code=PLUGIN_STOPPED", operationId, accountName);
            return;
        }
        try
        {
            Path output = SnapshotWriter.writeAtomically(RuneLite.RUNELITE_DIR.toPath(), accountName, json);
            deduplicator.succeeded(fingerprint);
            scheduler.exportSucceeded();
            if (running)
            {
                LOG.info(
                    "QSE_EXPORT_OK operationId={} account={} quests={} path={}",
                    operationId,
                    accountName,
                    questCount,
                    output);
            }
            else
            {
                LOG.warn(
                    "QSE_EXPORT_COMPLETED_DURING_SHUTDOWN operationId={} account={} path={} integrity=atomic",
                    operationId,
                    accountName,
                    output);
            }
        }
        catch (IOException | RuntimeException error)
        {
            deduplicator.failed(fingerprint);
            boolean retryScheduled = running && scheduler.retry();
            LOG.error(
                "QSE_WRITE_FAILED operationId={} account={} outputDirectory={} retryScheduled={} retryTicks={} recovery={}",
                operationId,
                accountName,
                SnapshotWriter.OUTPUT_DIRECTORY,
                retryScheduled,
                retryScheduled ? ExportScheduler.LOGIN_SETTLE_TICKS : 0,
                retryScheduled ? "fix_filesystem" : "wait_for_heartbeat_or_relogin",
                error);
        }
    }
}

package io.github.iamthecodedecoded.queststateexporter;

import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.Objects;
import java.util.regex.Pattern;

final class SnapshotWriter
{
    static final String OUTPUT_DIRECTORY = "quest-state-exporter";
    private static final Pattern UNSAFE_FILE_CHARACTER = Pattern.compile("[^a-zA-Z0-9 _-]");

    private SnapshotWriter()
    {
    }

    static Path outputPath(Path runeliteDirectory, String accountName)
    {
        Objects.requireNonNull(runeliteDirectory, "runeliteDirectory");
        if (accountName == null || accountName.trim().isEmpty())
        {
            throw new IllegalArgumentException("Account name must not be blank.");
        }
        String safeName = UNSAFE_FILE_CHARACTER.matcher(accountName).replaceAll("_");
        Path directory = runeliteDirectory.resolve(OUTPUT_DIRECTORY).toAbsolutePath().normalize();
        Path output = directory.resolve(safeName + ".json").normalize();
        if (!directory.equals(output.getParent()))
        {
            throw new IllegalArgumentException("Account name escaped the fixed output directory.");
        }
        return output;
    }

    static Path writeAtomically(Path runeliteDirectory, String accountName, String json) throws IOException
    {
        Objects.requireNonNull(json, "json");
        Path output = outputPath(runeliteDirectory, accountName);
        Files.createDirectories(output.getParent());
        Path temporary = Files.createTempFile(output.getParent(), output.getFileName() + ".", ".tmp");
        try
        {
            Files.writeString(
                temporary,
                json,
                StandardCharsets.UTF_8,
                StandardOpenOption.TRUNCATE_EXISTING,
                StandardOpenOption.WRITE);
            try (FileChannel channel = FileChannel.open(temporary, StandardOpenOption.WRITE))
            {
                channel.force(true);
            }
            try
            {
                Files.move(
                    temporary,
                    output,
                    StandardCopyOption.ATOMIC_MOVE,
                    StandardCopyOption.REPLACE_EXISTING);
            }
            catch (AtomicMoveNotSupportedException error)
            {
                throw new IOException("Atomic replacement is unavailable for " + output, error);
            }
            return output;
        }
        catch (IOException | RuntimeException error)
        {
            try
            {
                Files.deleteIfExists(temporary);
            }
            catch (IOException cleanupError)
            {
                error.addSuppressed(cleanupError);
            }
            throw error;
        }
    }
}

