package io.github.iamthecodedecoded.queststateexporter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import io.github.iamthecodedecoded.queststateexporter.ExportScheduler.ExportRequest;

import org.junit.Test;

public class ExportSchedulerTest
{
    @Test
    public void exportsOnceFiveTicksAfterLogin()
    {
        ExportScheduler scheduler = new ExportScheduler();
        scheduler.loggedIn();
        for (int tick = 0; tick < 4; tick++)
        {
            assertEquals(ExportRequest.NONE, scheduler.gameTick());
        }
        assertEquals(ExportRequest.FORCE, scheduler.gameTick());
        assertEquals(ExportRequest.NONE, scheduler.gameTick());
    }

    @Test
    public void neverExportsWhileLoggedOut()
    {
        ExportScheduler scheduler = new ExportScheduler();
        scheduler.varbitChanged();
        assertEquals(ExportRequest.NONE, scheduler.gameTick());
        scheduler.loggedIn();
        scheduler.loggedOut();
        for (int tick = 0; tick < 10; tick++)
        {
            assertEquals(ExportRequest.NONE, scheduler.gameTick());
        }
    }

    @Test
    public void varbitChangeSchedulesOneDebouncedExport()
    {
        ExportScheduler scheduler = new ExportScheduler();
        scheduler.loggedIn();
        for (int tick = 0; tick < 5; tick++)
        {
            scheduler.gameTick();
        }
        scheduler.varbitChanged();
        scheduler.varbitChanged();
        assertEquals(ExportRequest.CAPTURE, scheduler.gameTick());
        assertEquals(ExportRequest.NONE, scheduler.gameTick());
    }

    @Test
    public void forcesARefreshBeforeAnUnchangedSnapshotBecomesStale()
    {
        ExportScheduler scheduler = new ExportScheduler();
        scheduler.loggedIn();
        for (int tick = 0; tick < ExportScheduler.LOGIN_SETTLE_TICKS; tick++)
        {
            scheduler.gameTick();
        }
        for (int tick = 0; tick < ExportScheduler.HEARTBEAT_TICKS - 1; tick++)
        {
            assertEquals(ExportRequest.NONE, scheduler.gameTick());
        }
        assertEquals(ExportRequest.FORCE, scheduler.gameTick());
    }

    @Test
    public void retriesAreBoundedUntilTheNextHeartbeatProbe()
    {
        ExportScheduler scheduler = new ExportScheduler();
        scheduler.loggedIn();
        advanceToRequest(scheduler, ExportRequest.FORCE);

        for (int attempt = 0; attempt < ExportScheduler.MAX_CONSECUTIVE_RETRIES; attempt++)
        {
            assertTrue(scheduler.retry());
            advanceToRequest(scheduler, ExportRequest.FORCE);
        }
        assertFalse(scheduler.retry());
        scheduler.varbitChanged();
        assertEquals(ExportRequest.NONE, scheduler.gameTick());

        advanceToRequest(scheduler, ExportRequest.FORCE);
        assertTrue(scheduler.retry());
    }

    @Test
    public void successfulWriteResetsTheRetryBudget()
    {
        ExportScheduler scheduler = new ExportScheduler();
        scheduler.loggedIn();
        advanceToRequest(scheduler, ExportRequest.FORCE);
        for (int attempt = 0; attempt < ExportScheduler.MAX_CONSECUTIVE_RETRIES; attempt++)
        {
            assertTrue(scheduler.retry());
            advanceToRequest(scheduler, ExportRequest.FORCE);
        }
        scheduler.exportSucceeded();
        assertTrue(scheduler.retry());
    }

    private static void advanceToRequest(ExportScheduler scheduler, ExportRequest expected)
    {
        for (int tick = 0; tick <= ExportScheduler.HEARTBEAT_TICKS; tick++)
        {
            ExportRequest request = scheduler.gameTick();
            if (request != ExportRequest.NONE)
            {
                assertEquals(expected, request);
                return;
            }
        }
        throw new AssertionError("No export request arrived before the heartbeat deadline.");
    }
}

package io.github.iamthecodedecoded.queststateexporter;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class PayloadDeduplicatorTest
{
    @Test
    public void skipsPayloadWhileQueuedAndAfterSuccessfulWrite()
    {
        PayloadDeduplicator deduplicator = new PayloadDeduplicator();

        assertTrue(deduplicator.tryQueue("account-a\nquest-state-1"));
        assertFalse(deduplicator.tryQueue("account-a\nquest-state-1"));

        deduplicator.succeeded("account-a\nquest-state-1");
        assertFalse(deduplicator.tryQueue("account-a\nquest-state-1"));
        assertTrue(deduplicator.tryQueue("account-a\nquest-state-2"));
    }

    @Test
    public void failedWriteCanBeQueuedAgain()
    {
        PayloadDeduplicator deduplicator = new PayloadDeduplicator();

        assertTrue(deduplicator.tryQueue("payload"));
        deduplicator.failed("payload");
        assertTrue(deduplicator.tryQueue("payload"));
    }

    @Test
    public void loginForcesARefreshOfAnUnchangedPayload()
    {
        PayloadDeduplicator deduplicator = new PayloadDeduplicator();

        assertTrue(deduplicator.tryQueue("payload"));
        deduplicator.succeeded("payload");
        deduplicator.forceNext();
        assertTrue(deduplicator.tryQueue("payload"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsBlankFingerprints()
    {
        new PayloadDeduplicator().tryQueue("  ");
    }
}

package io.github.iamthecodedecoded.queststateexporter;

import com.google.gson.Gson;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.RuneLite;

public final class PluginLifecycleSmokeMain
{
    private PluginLifecycleSmokeMain()
    {
    }

    public static void main(String[] arguments) throws Exception
    {
        Path pluginArtifact = pluginArtifact();
        String pluginSha256 = sha256(pluginArtifact);
        QuestStateExporterPlugin plugin = new QuestStateExporterPlugin();
        inject(plugin, "client", loggedOutClient());
        inject(plugin, "gson", new Gson());

        plugin.startUp();
        try
        {
            plugin.onVarbitChanged(new VarbitChanged());
            for (int tick = 0; tick < 10; tick++)
            {
                plugin.onGameTick(new GameTick());
            }
        }
        finally
        {
            plugin.shutDown();
        }

        Path runeliteDirectory = RuneLite.RUNELITE_DIR.toPath().toAbsolutePath().normalize();
        Path outputDirectory = runeliteDirectory.resolve(SnapshotWriter.OUTPUT_DIRECTORY);
        Path credentials = runeliteDirectory.resolve("credentials.properties");
        if (Files.exists(outputDirectory))
        {
            throw new IllegalStateException("Logged-out lifecycle created a quest output directory: " + outputDirectory);
        }
        if (Files.exists(credentials))
        {
            throw new IllegalStateException("Logged-out lifecycle found a credential file: " + credentials);
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("status", "passed");
        result.put("gameState", GameState.LOGIN_SCREEN.name());
        result.put("questOutputCreated", false);
        result.put("credentialsFilePresent", false);
        result.put("hostInputUsed", false);
        result.put("syntheticInputUsed", false);
        result.put("pluginArtifact", pluginArtifact.toString());
        result.put("pluginSha256", pluginSha256);
        System.out.println(new Gson().toJson(result));
    }

    private static Path pluginArtifact() throws Exception
    {
        URI location = QuestStateExporterPlugin.class
            .getProtectionDomain()
            .getCodeSource()
            .getLocation()
            .toURI();
        Path artifact = Path.of(location).toAbsolutePath().normalize();
        if (!Files.isRegularFile(artifact) || !artifact.getFileName().toString().endsWith(".jar"))
        {
            throw new IllegalStateException("Plugin was not loaded from a packaged JAR: " + artifact);
        }
        return artifact;
    }

    private static String sha256(Path path) throws Exception
    {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream stream = Files.newInputStream(path))
        {
            byte[] buffer = new byte[8192];
            int read;
            while ((read = stream.read(buffer)) >= 0)
            {
                digest.update(buffer, 0, read);
            }
        }
        StringBuilder value = new StringBuilder();
        for (byte item : digest.digest())
        {
            value.append(String.format("%02x", item & 0xff));
        }
        return value.toString();
    }

    private static void inject(QuestStateExporterPlugin plugin, String fieldName, Object value) throws Exception
    {
        Field field = QuestStateExporterPlugin.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(plugin, value);
    }

    private static Client loggedOutClient()
    {
        return (Client) Proxy.newProxyInstance(
            Client.class.getClassLoader(),
            new Class<?>[]{Client.class},
            (proxy, method, arguments) ->
            {
                switch (method.getName())
                {
                    case "getGameState":
                        return GameState.LOGIN_SCREEN;
                    case "toString":
                        return "LoggedOutClient";
                    case "hashCode":
                        return System.identityHashCode(proxy);
                    case "equals":
                        return proxy == arguments[0];
                    default:
                        Class<?> returnType = method.getReturnType();
                        if (!returnType.isPrimitive())
                        {
                            return null;
                        }
                        if (returnType == boolean.class)
                        {
                            return false;
                        }
                        if (returnType == char.class)
                        {
                            return '\0';
                        }
                        return 0;
                }
            });
    }
}

package io.github.iamthecodedecoded.queststateexporter;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Quest;

public final class QuestCatalogMain
{
    private QuestCatalogMain()
    {
    }

    public static void main(String[] arguments) throws Exception
    {
        if (arguments.length != 1)
        {
            throw new IllegalArgumentException("Expected one output path.");
        }

        List<Map<String, String>> entries = new ArrayList<>(Quest.values().length);
        for (Quest quest : Quest.values())
        {
            Map<String, String> entry = new LinkedHashMap<>();
            entry.put("id", quest.name());
            entry.put("name", quest.getName());
            entries.add(entry);
        }

        Map<String, Object> catalog = new LinkedHashMap<>();
        catalog.put("source", "net.runelite.api.Quest.values");
        catalog.put("entries", entries);

        Path output = Path.of(arguments[0]);
        Files.createDirectories(output.getParent());
        Gson gson = new GsonBuilder().setPrettyPrinting().create();
        Files.writeString(output, gson.toJson(catalog) + System.lineSeparator(), StandardCharsets.UTF_8);
    }
}

