package io.github.iamthecodedecoded.queststateexporter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.time.Instant;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import org.junit.Test;

public class QuestSnapshotBuilderTest
{
    @SuppressWarnings("unchecked")
    @Test
    public void capturesEveryQuestWithConsistentCounts()
    {
        Map<String, Object> snapshot = QuestSnapshotBuilder.capture(
            QuestClientFixture.client(),
            "Psalm 19-14",
            Instant.parse("2026-08-20T17:00:00Z"));

        assertEquals("1.0.0", snapshot.get("schemaVersion"));
        assertEquals("1.0.0", snapshot.get("exportVersion"));
        assertEquals("Psalm 19-14", snapshot.get("rsn"));
        assertEquals("2026-08-20T17:00:00Z", snapshot.get("timestampIso"));

        Map<String, Object> quests = (Map<String, Object>) snapshot.get("quests");
        List<Map<String, Object>> entries = (List<Map<String, Object>>) quests.get("entries");
        assertEquals(Quest.values().length, entries.size());
        assertEquals(entries.size(), ((Number) quests.get("total")).intValue());
        assertEquals(0, ((Number) quests.get("unknown")).intValue());

        int declared = ((Number) quests.get("finished")).intValue()
            + ((Number) quests.get("inProgress")).intValue()
            + ((Number) quests.get("notStarted")).intValue();
        assertEquals(entries.size(), declared);

        Set<String> ids = new HashSet<>();
        Set<String> states = new HashSet<>();
        for (Map<String, Object> entry : entries)
        {
            assertTrue(ids.add((String) entry.get("id")));
            states.add((String) entry.get("state"));
        }
        assertTrue(ids.contains("COOKS_ASSISTANT"));
        assertTrue(ids.contains("DRAGON_SLAYER_I"));
        assertTrue(ids.contains("ROMEO__JULIET"));
        assertEquals(Set.of("FINISHED", "IN_PROGRESS", "NOT_STARTED"), states);
        assertEquals(42, ((Number) quests.get("questPoints")).intValue());
        assertEquals(Set.of("schemaVersion", "exportVersion", "timestampIso", "rsn", "quests"), snapshot.keySet());
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsBlankAccountName()
    {
        QuestSnapshotBuilder.capture(QuestClientFixture.client(), "   ", Instant.now());
    }
}

