package io.github.iamthecodedecoded.queststateexporter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.stream.Stream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class SnapshotWriterTest
{
    @Rule
    public TemporaryFolder temporaryFolder = new TemporaryFolder();

    @Test
    public void writesAndAtomicallyReplacesOneAccountFile() throws Exception
    {
        Path runeliteDir = temporaryFolder.newFolder("runelite").toPath();
        Path first = SnapshotWriter.writeAtomically(runeliteDir, "Psalm 19-14", "{\"version\":1}\n");
        Path second = SnapshotWriter.writeAtomically(runeliteDir, "Psalm 19-14", "{\"version\":2}\n");

        assertEquals(first, second);
        assertEquals(runeliteDir.resolve("quest-state-exporter").resolve("Psalm 19-14.json"), second);
        assertEquals("{\"version\":2}\n", Files.readString(second, StandardCharsets.UTF_8));
        try (Stream<Path> files = Files.list(second.getParent()))
        {
            assertEquals(1L, files.count());
        }
    }

    @Test
    public void maliciousAccountNameCannotEscapeFixedDirectory()
    {
        Path runeliteDir = temporaryFolder.getRoot().toPath();
        Path output = SnapshotWriter.outputPath(runeliteDir, "..\\..\\secret/<bad>:*?|");
        Path fixedDirectory = runeliteDir.resolve("quest-state-exporter").toAbsolutePath().normalize();

        assertEquals(fixedDirectory, output.getParent());
        assertTrue(output.getFileName().toString().matches("[a-zA-Z0-9 _-]+\\.json"));
        assertFalse(output.getFileName().toString().contains(".."));
    }

    @Test(expected = IOException.class)
    public void writeFailureIsNotReportedAsSuccess() throws Exception
    {
        Path blocked = temporaryFolder.newFile("blocked").toPath();
        SnapshotWriter.writeAtomically(blocked, "Psalm 19-14", "{}\n");
    }
}
